import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"既濟","description":"周易集解 - 既濟","frontmatter":{"title":"既濟","description":"周易集解 - 既濟"},"headers":[],"relativePath":"classics/jijie/063.md","filePath":"classics/jijie/063.md"}'),l={name:"classics/jijie/063.md"};function n(d,a,t,p,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="既濟" tabindex="-1">既濟 <a class="header-anchor" href="#既濟" aria-label="Permalink to “既濟”">​</a></h1><h2 id="既濟-1" tabindex="-1">既濟 <a class="header-anchor" href="#既濟-1" aria-label="Permalink to “既濟”">​</a></h2><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>既濟，亨小，利貞。</p><h2 id="卦辭注" tabindex="-1">卦辭注 <a class="header-anchor" href="#卦辭注" aria-label="Permalink to “卦辭注”">​</a></h2><p>《序卦》曰：有過物者必濟，故受之以既濟。</p><p>韓康伯曰：行過乎儉恭，禮過乎儉，可以矯世厲俗，有所濟也。</p><p>虞翻曰：泰五之二。小，謂二也。柔得中。故亨小。六爻得位，各正性命，保合大和故利貞矣。</p><p>虞翻曰：初，始也。謂泰乾。乾知大始，故稱初。坤五之乾二，得正處中，故初吉，柔得中也。</p><p>虞翻曰：泰坤稱亂。二上之五，終止於泰，則反成否。子弒其父，臣弒其君，天下無邦，終窮成坤，故亂，其道窮。</p><h2 id="彖" tabindex="-1">彖 <a class="header-anchor" href="#彖" aria-label="Permalink to “彖”">​</a></h2><p>《彖》曰：既濟亨，小者亨也。利貞，剛柔正而位當也。初吉，柔得中也。終止則亂，其道窮也。</p><h2 id="彖傳注" tabindex="-1">彖傳注 <a class="header-anchor" href="#彖傳注" aria-label="Permalink to “彖傳注”">​</a></h2><p>荀爽曰：天地既交，陽升陰降，故小者亨也。</p><p>侯果曰：此本泰卦。六五降二，九二升五，是剛柔正當位也。</p><p>虞翻曰：中，謂二。</p><p>虞翻曰：反否終坤，故其道窮也。</p><p>侯果曰：剛得正，柔得中，故初吉也。正有終極，濟有息止，止則窮亂，故曰終止則亂，其道窮也。一曰：殷亡周興之卦也。成湯應天，初吉也。商辛毒痡，終止也。由止，故物亂而窮也。物不可窮，窮則復始，周受其未濟而興焉。《乾鑿度》曰：既濟未濟者，所以明戒慎，全王道也。</p><h2 id="象" tabindex="-1">象 <a class="header-anchor" href="#象" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：水在火上，既濟。君子以思患而豫防之。</p><h2 id="象傳注" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注" aria-label="Permalink to “象傳注”">​</a></h2><p>荀爽曰：六爻既正，必當復亂，故君子象之。思患而豫防之，治不忘亂也。</p><h2 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h2><p>初九，曳其輪，濡其尾，無咎。</p><h2 id="初九注" tabindex="-1">初九注 <a class="header-anchor" href="#初九注" aria-label="Permalink to “初九注”">​</a></h2><h2 id="象-1" tabindex="-1">象 <a class="header-anchor" href="#象-1" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：曳其輪，義無咎也。</p><h2 id="象傳注-1" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-1" aria-label="Permalink to “象傳注”">​</a></h2><p>宋衷曰：離者兩陽一陰。陰方陽圓，輿輪之象也。其一在坎中，以火入水，必敗，故曰曳其輪也。初在後，稱尾。尾濡曳，咎也。得正有應，於義可以危而無咎矣。</p><h2 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h2><p>六二，婦喪其茀，勿逐，七日得。</p><h2 id="六二注" tabindex="-1">六二注 <a class="header-anchor" href="#六二注" aria-label="Permalink to “六二注”">​</a></h2><p>虞翻曰：離為婦。泰坤為喪。茀，髮，謂鬒髮也。一名婦人之首飾。坎為玄雲，故稱髮。《詩》曰：鬒髮如雲。乾為首，坎為美；五取乾二之坤為坎，坎為盜，故婦喪其茀。泰震為七，故勿逐，七日得。與睽喪馬勿逐同義。髴，或作茀。俗說以髴為婦人蔽膝之茀，非也。</p><h2 id="象-2" tabindex="-1">象 <a class="header-anchor" href="#象-2" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：七日得，以中道也。</p><h2 id="象傳注-2" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-2" aria-label="Permalink to “象傳注”">​</a></h2><p>王肅曰：體柔應五，履順承剛，婦人之義也。茀，首飾。坎為盜。離為婦。喪其茀，鄰於盜也。勿逐自得，履中道也。二五相應，故七日得也。</p><h2 id="九三" tabindex="-1">九三 <a class="header-anchor" href="#九三" aria-label="Permalink to “九三”">​</a></h2><p>九三，高宗伐鬼方，三年克之，小人勿用。</p><h2 id="九三注" tabindex="-1">九三注 <a class="header-anchor" href="#九三注" aria-label="Permalink to “九三注”">​</a></h2><p>虞翻曰：高宗，殷王武丁。鬼方，國名。乾為高宗，坤為鬼方；乾二之坤五。故高宗伐鬼方。坤為年，位在三，故三年。坤為小人，二上克五，故三年克之，小人勿用。《象》曰：｢憊也｣。</p><p>乾寶曰：高宗，殷中興之君。鬼方，北方國也。高宗嘗伐鬼方，三年而後克之。離為戈兵，故稱伐。坎當北方，故稱鬼。在既濟之家，而述先代之功，以明周因於殷，有所弗革也。</p><h2 id="象-3" tabindex="-1">象 <a class="header-anchor" href="#象-3" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：三年克之，憊也。</p><h2 id="象傳注-3" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-3" aria-label="Permalink to “象傳注”">​</a></h2><p>侯果曰：伐鬼方者，興衰除闇之徵也。上六闇極，九三徵之，三舉方及，故曰三年克之。興役動眾，聖猶疲憊，則非小人能為，故曰小人勿用。</p><p>虞翻曰：坎為勞，故憊也。</p><h2 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h2><p>六四，繻有衣袽，終日戒。</p><h2 id="六四注" tabindex="-1">六四注 <a class="header-anchor" href="#六四注" aria-label="Permalink to “六四注”">​</a></h2><p>虞翻曰：乾為衣，故稱繻。袽，敗衣也。乾二之五，衣象裂壞，故繻有衣袽。離為日，坎為盜，在兩坎間，故終日戒。謂伐鬼方三年乃克。旅人勤勞，衣服皆敗，鬼方之民，猶或寇竊，故終日戒也。</p><h2 id="象-4" tabindex="-1">象 <a class="header-anchor" href="#象-4" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：終日戒，有所疑也。</p><h2 id="象傳注-4" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-4" aria-label="Permalink to “象傳注”">​</a></h2><p>盧氏曰：繻者，布帛端末之識也。袽者，殘幣帛，可拂拭器物也。繻有為衣袽之道也。四處明闇之際，貴賤無恆，猶或為衣或為袽也。履多懼之地，上承帝主，故終日戒慎，有所疑懼也。</p><h2 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h2><p>九五，東鄰殺牛，不如西鄰之禴祭，實受其福。</p><h2 id="九五注" tabindex="-1">九五注 <a class="header-anchor" href="#九五注" aria-label="Permalink to “九五注”">​</a></h2><p>虞翻曰：泰震為東，兌為西，坤為牛，震動五殺坤，故東鄰殺牛。在坎多眚，為陰所乘，故不如西鄰之禴祭。禴，夏祭也。離為夏。兌動二，體離明。得正承五，順三。故實受其福，吉大來也。</p><h2 id="象-5" tabindex="-1">象 <a class="header-anchor" href="#象-5" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：東鄰殺牛，不如西鄰之時也。實受其福，吉大來也。</p><h2 id="象傳注-5" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-5" aria-label="Permalink to “象傳注”">​</a></h2><p>崔憬曰：居中當位。於既濟之時，則當是周受命之日也。五坎為月。月出西方，西鄰之謂也。二應在離，離為日。日出東方，東鄰之謂也。離又為牛，坎水克離火，東鄰殺牛之象。禴，殷春祭之名。案《尚書》：克殷之歲，厥四月哉生明。王來自商，至於豐。丁未，祀於周廟。四月殷之三月，春也。則明西鄰之禴祭，得其時而受祉福也。</p><p>盧氏曰：明鬼享德不享味也。故德厚者，吉大來也。</p><h2 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h2><p>上六，濡其首，厲。</p><h2 id="上六注" tabindex="-1">上六注 <a class="header-anchor" href="#上六注" aria-label="Permalink to “上六注”">​</a></h2><p>虞翻曰：乾為首，五從二上在坎中，故濡其首，厲。位極乘陽，故何可久。</p><h2 id="象-6" tabindex="-1">象 <a class="header-anchor" href="#象-6" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：濡其首厲，何可久也。</p><h2 id="象傳注-6" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-6" aria-label="Permalink to “象傳注”">​</a></h2><p>荀爽曰：居上濡五，處高居盛，必當復危，故何可久也。</p>',72)])])}const f=e(l,[["render",n]]);export{b as __pageData,f as default};
